-- No 'Salvar Base' do workflow [Serena] Sync Base de Treinamento (D71uJKMi3u442bL0). $1 = payload do 'Extrair Texto'.
-- Trava de versao (19/10/2026): so regrava com hash diferente E versao do site > base_versao, ou com force.
with d as (select $1::jsonb as j), v as (select case when (d.j->>'versao') ~ '^[0-9]+(\.[0-9]+)*$' then string_to_array(d.j->>'versao', '.')::int[] else array[0] end as site, coalesce((select case when valor ~ '^[0-9]+(\.[0-9]+)*$' then string_to_array(valor, '.')::int[] end from serena_config where chave = 'base_versao'), array[0]) as banco from d), dif as (select (select valor from serena_config where chave = 'base_hash') is distinct from (d.j->>'hash') as h, coalesce((d.j->>'force')::boolean, false) as f from d), mudou as (select (dif.f or (dif.h and v.site > v.banco)) as m, (dif.h and not dif.f and not (v.site > v.banco)) as bloqueado from dif, v), up as (insert into serena_config (chave, valor, atualizado_em) select 'base_treinamento', d.j->>'texto', now() from d, mudou where mudou.m on conflict (chave) do update set valor = excluded.valor, atualizado_em = now() returning length(valor) as tamanho), hs as (insert into serena_config (chave, valor, atualizado_em) select 'base_hash', d.j->>'hash', now() from d, mudou where mudou.m on conflict (chave) do update set valor = excluded.valor, atualizado_em = now() returning 1), vs as (insert into serena_config (chave, valor, atualizado_em) select 'base_versao', d.j->>'versao', now() from d, mudou where mudou.m and (d.j->>'versao') ~ '^[0-9]+(\.[0-9]+)*$' on conflict (chave) do update set valor = excluded.valor, atualizado_em = now() returning 1), et as (insert into serena_config (chave, valor, atualizado_em) select 'base_etag', d.j->>'etag', now() from d where nullif(d.j->>'etag', '') is not null on conflict (chave) do update set valor = excluded.valor, atualizado_em = now() returning 1) select (select m from mudou) as mudou, (select bloqueado from mudou) as bloqueado, (select array_to_string(banco, '.') from v) as versao_banco, (select tamanho from up) as tamanho, (select count(*) from hs)::int as hash_gravado, (select count(*) from vs)::int as versao_gravada, (select count(*) from et)::int as etag_gravado
